#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# The one-time setup of the Mac release (DEVELOP.md, "One-time setup on your
# Mac"): the three GitHub secrets that release.yml's mac job needs. Run it on
# your Mac from anywhere in the repo:
#
#   mac/scripts/setup-release-secrets.sh
#
# Nothing is written to a .env file; the values go only to GitHub, the
# EdDSA key also stays in your login keychain, and the certificate stays in
# ~/PianoTunah-signing.p12.

# shellcheck source=lib.sh
source "$(dirname "$0")/lib.sh"
ENV_FILE=/dev/null # no .env: never offer or write saved values
REPO=riborg/pianotunah
# Every gh call goes to this repo, wherever the script is run from.
export GH_REPO=$REPO
P12="$HOME/PianoTunah-signing.p12"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
chmod 700 "$work"

TOTAL_STAGES=5

# The questions need a person at a terminal; without one, read would fail
# and "Saved it?" below would ask forever.
[[ -t 0 ]] || die "run this in a terminal"

# The library's banner speaks of a browser and saved .env values; this
# wizard runs commands and keeps nothing in a file.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard runs the commands and tells you what each one is for.\n' "$DIM"
  printf '  Stop any time with Ctrl-C and run it again: the key in your keychain\n'
  printf '  and an existing .p12 are kept.%s\n' "$RESET"
  pause "Ready to start?"
}

banner "Piano Tunah: secrets for the Mac release"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "The secrets are made here and stored in $REPO's Actions secrets."
[[ "$(uname)" == Darwin ]] || die "run this on your Mac"
for tool in gh xcodegen xcodebuild openssl security; do
  command -v "$tool" >/dev/null 2>&1 || die "$tool is missing (xcodegen: brew install xcodegen; gh: brew install gh)"
done
gh auth status >/dev/null 2>&1 || die "gh is not signed in: run gh auth login, then this again"
cd "$mac_dir"
[[ "$(gh repo view --json nameWithOwner -q .nameWithOwner)" == "$REPO" ]] \
  || die "gh does not point at $REPO from $mac_dir"
existing=$(gh secret list -R "$REPO" --json name -q '.[].name' \
  | grep -E '^(SPARKLE_ED_PRIVATE_KEY|MAC_SIGNING_P12|MAC_SIGNING_PASSWORD)$' || true)
if [[ -n "$existing" ]]; then
  warn "These secrets exist already and would be replaced:"
  for s in $existing; do note "  - $s"; done
  warn "The key in your keychain and $P12 are reused if they exist."
  warn "Without them, a new EdDSA key stops installed apps from accepting"
  warn "updates, and a new certificate makes macOS ask for the microphone again."
  confirm "Replace them?" || die "stopped; nothing changed"
fi
step "gh, xcodegen, Xcode and openssl are there, and gh is signed in."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Fetch Sparkle's tools"
say "Generates the Xcode project and resolves the Swift packages into"
say "mac/build/SourcePackages, where Sparkle's generate_keys is. Takes a minute."
sparkle=$(sparkle_bin)
step "generate_keys is in $sparkle"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The EdDSA key for updates (SPARKLE_ED_PRIVATE_KEY)"
say "generate_keys makes the key in your login keychain, or finds the one"
say "already there; the keychain is your backup of it."
warn "macOS may ask for your login password to let generate_keys use the keychain."
pause "Press Enter to run generate_keys"
"$sparkle/generate_keys"
public=$("$sparkle/generate_keys" -p)
"$sparkle/generate_keys" -x "$work/ed.key" >/dev/null
SPARKLE_ED_PRIVATE_KEY=$(cat "$work/ed.key")
rm -f "$work/ed.key"
# The release derives the public key from the private one (ed-key.sh); check
# that it gives the keychain's.
derived=$(SPARKLE_ED_PRIVATE_KEY="$SPARKLE_ED_PRIVATE_KEY" "$scripts_dir/ed-key.sh" public)
[[ "$derived" == "$public" ]] || die "the exported key gives $derived, the keychain has $public"
step "Public key: $public"
set_secret SPARKLE_ED_PRIVATE_KEY "$SPARKLE_ED_PRIVATE_KEY"
unset SPARKLE_ED_PRIVATE_KEY
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The signing certificate (MAC_SIGNING_P12, MAC_SIGNING_PASSWORD)"
if [[ -e "$P12" ]]; then
  say "$P12 is there already: it is kept, as a new certificate is a new"
  say "identity for macOS."
  ask_secret MAC_SIGNING_PASSWORD "Its password (from your password manager):"
  export MAC_SIGNING_PASSWORD
  openssl pkcs12 -in "$P12" -noout -passin env:MAC_SIGNING_PASSWORD 2>/dev/null \
    || die "that password does not open $P12"
else
  say "A self-signed certificate, valid for 10 years, saved with its key to"
  say "$P12 under a new random password:"
  MAC_SIGNING_PASSWORD=$(openssl rand -base64 24)
  export MAC_SIGNING_PASSWORD
  printf '\n    %s%s%s\n\n' "$BOLD" "$MAC_SIGNING_PASSWORD" "$RESET"
  step "Save this password in your password manager now, with the file's path."
  note "You need it if the .p12 is ever set again; it is not shown again."
  until confirm "Saved it?"; do :; done
  "$scripts_dir/make-signing-cert.sh" "$P12"
fi
set_secret MAC_SIGNING_P12 "$(base64 < "$P12" | tr -d '\n')"
set_secret MAC_SIGNING_PASSWORD "$MAC_SIGNING_PASSWORD"
unset MAC_SIGNING_PASSWORD
step "Keep $P12 (a backup in your password manager is good too)."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Check GitHub"
gh secret list -R "$REPO"
missing=""
for s in SPARKLE_ED_PRIVATE_KEY MAC_SIGNING_P12 MAC_SIGNING_PASSWORD; do
  gh secret list -R "$REPO" --json name -q '.[].name' | grep -qx "$s" || missing="$missing $s"
done
if [[ -n "$missing" ]]; then
  warn "Missing:$missing"
else
  step "All three are set. The next v* tag publishes the Mac app with its appcast."
fi
pause "Press Enter for the summary"

finish
